        public static Vector128<byte> AsByte<T>(this Vector128<T> vector) => vector.As<T, byte>();

        /// <summary>Reinterprets a <see cref="Vector128{T}" /> as a new <see langword="Vector128&lt;Double&gt;" />.</summary>
